window.DUAL_DATA={"cats":[{"id":1,"name":"Ich mit mir","range":"01–07","topic":"Selbstbild, Antrieb, Wert","color":"#0E7F93","tint":"rgba(14,127,147,0.10)"},{"id":2,"name":"Kopf an, Kopf aus","range":"08–14","topic":"Denken, Fühlen, Deuten","color":"#C42E7C","tint":"rgba(196,46,124,0.10)"},{"id":3,"name":"Zusammen ist man weniger allein","range":"15–21","topic":"Nähe, Rücksicht, Wahrheit","color":"#1FAFC7","tint":"rgba(31,175,199,0.13)"},{"id":4,"name":"Machen, lassen, weitermachen","range":"22–28","topic":"Handeln, Planen, Aufschieben","color":"#E8489A","tint":"rgba(232,72,154,0.11)"},{"id":5,"name":"Meins, deins, unseres","range":"29–35","topic":"Geben, Haben, Fairness","color":"#18202E","tint":"rgba(24,32,46,0.08)"},{"id":6,"name":"Das Leben mischt mit","range":"36–42","topic":"Gefühl, Erinnerung, Abschied","color":"#5A6270","tint":"rgba(90,98,112,0.10)"}],"joker":{"id":0,"name":"Zusatzkarte · Joker","range":"43","topic":"Geduld","color":"#C42E7C","tint":"rgba(196,46,124,0.10)"},"cards":[{"nr":"01","n":1,"title":"PERFEKTIONISMUS","titleSub":"","name":"Perfektionismus","catId":1,"catName":"Ich mit mir","catLabel":"Kategorie 1","color":"#0E7F93","tint":"rgba(14,127,147,0.10)","story":[{"t":"„Warum hast du mir deinen Brief nie geschickt?“, fragte sie.","q":true},{"t":"„Er war noch nicht gut genug.“","q":true},{"t":"„Was fehlte?“","q":true},{"t":"„Am Anfang die richtigen Worte. Dann ein schönerer Schluss.“","q":true},{"t":"„Und jetzt?“","q":true},{"t":"Er faltete das Papier auseinander.","q":false},{"t":"„Jetzt stimmt alles.“","q":true},{"t":"„Dann schick ihn.“","q":true},{"t":"Er betrachtete die Adresse.","q":false},{"t":"„Sie wohnt dort nicht mehr.“","q":true},{"t":"Die Frau schwieg eine Weile.","q":false},{"t":"„Was wolltest du ihr sagen?“","q":true},{"t":"„Dass ich sie gern wiedersehen würde.“","q":true},{"t":"„Dieser Satz hätte mir gereicht.“","q":true}],"sides":"Qualität schaffen ↔ nicht fertig werden.","sideA":"Qualität schaffen","sideB":"nicht fertig werden","dreh":"Wann macht Sorgfalt etwas besser – und wann nur später?","szene":"Dein Geburtstagsvideo für deine beste Freundin ist fertig und lustig. Du könntest noch eine Stunde am Schnitt feilen – oder es endlich schicken, bevor der Tag vorbei ist. Was tust du? Und was könnte dich anders entscheiden lassen?","wenn":"… sie sich auch über ein verwackeltes Handyvideo gefreut hätte?","bucay":"„Selbstablehnung“: Ein Text, in dem die Ablehnung der eigenen Person spricht – sie verkleidet sich unter anderem als Perfektionismus und tauscht „Ich bin“ gegen „Ich sollte sein“.","bruecke":"Für wen polierst du eigentlich – für die Person oder für die Likes?","joker":false},{"nr":"02","n":2,"title":"MUT","titleSub":"","name":"Mut","catId":1,"catName":"Ich mit mir","catLabel":"Kategorie 1","color":"#0E7F93","tint":"rgba(14,127,147,0.10)","story":[{"t":"„Ich habe mich getraut“, sagte er. „Ich habe vor allen widersprochen.“","q":true},{"t":"„Und?“","q":true},{"t":"„Meine Stimme hat gezittert.“","q":true},{"t":"„Haben sie dich verstanden?“","q":true},{"t":"„Ja.“","q":true},{"t":"„Dann hat sie offenbar funktioniert.“","q":true},{"t":"Er setzte sich neben sie.","q":false},{"t":"„Danach habe ich noch zehn Minuten weitergeredet.“","q":true},{"t":"„Warum?“","q":true},{"t":"„Weil ich beweisen wollte, dass ich keine Angst habe.“","q":true},{"t":"„War dein erster Satz richtig?“","q":true},{"t":"„Ja.“","q":true},{"t":"„Und die anderen?“","q":true},{"t":"Er verzog das Gesicht.","q":false},{"t":"„Die hätten eine kleine Pause gut vertragen.“","q":true}],"sides":"Über dich hinauswachsen ↔ dich übernehmen.","sideA":"Über dich hinauswachsen","sideB":"dich übernehmen","dreh":"Wann wächst du an einem Schritt – und wann übernimmst du dich?","szene":"Beim Abendessen mit Freunden macht jemand einen Witz, den du daneben findest. Alle lachen. Sagst du sofort etwas, fragst du nach, wie er gemeint war, oder schreibst du der Person später? Und was könnte dich anders entscheiden lassen?","wenn":"… die Person, über die der Witz ging, mit am Tisch sitzt?","bucay":"„Flügel sind zum Fliegen da“: Ein Vater zeigt dem Sohn: Wer fliegen will, braucht Höhe – und muss ein Risiko eingehen.","bruecke":"Von welcher Höhe springst du wirklich – und von welcher nur für die Story?","joker":false},{"nr":"03","n":3,"title":"SELBSTZWEIFEL","titleSub":"","name":"Selbstzweifel","catId":1,"catName":"Ich mit mir","catLabel":"Kategorie 1","color":"#0E7F93","tint":"rgba(14,127,147,0.10)","story":[{"t":"„Ich traue meinem Urteil nicht“, sagte er.","q":true},{"t":"Die Frau reichte ihm eine Birne.","q":false},{"t":"„Ist die reif?“","q":true},{"t":"Er drückte vorsichtig dagegen, roch daran und nickte.","q":false},{"t":"„Ich denke schon.“","q":true},{"t":"„Dann iss.“","q":true},{"t":"Er betrachtete die Birne.","q":false},{"t":"„Vielleicht sollte ich jemanden fragen.“","q":true},{"t":"„Du hast sie geprüft.“","q":true},{"t":"„Ich könnte mich irren.“","q":true},{"t":"„Natürlich.“","q":true},{"t":"Er legte die Birne auf die Bank.","q":false},{"t":"Eine Weile saßen sie schweigend da.","q":false},{"t":"„Worauf wartest du?“, fragte sie.","q":true},{"t":"„Auf Sicherheit.“","q":true},{"t":"Sie nahm die Birne und biss hinein.","q":false},{"t":"„Dann war es gut, dass wir keine Avocado genommen haben.“","q":true}],"sides":"Dich hinterfragen ↔ dich kleinmachen.","sideA":"Dich hinterfragen","sideB":"dich kleinmachen","dreh":"Wann schützt dich ein Zweifel – und wann hält er dich klein?","szene":"Ein Freund fragt, ob du auf seiner Hochzeit eine Rede hältst. Du findest, andere könnten das besser. Sagst du zu oder schlägst du jemand anderen vor? Und was könnte dich anders entscheiden lassen?","wenn":"… er sich an diesem Tag genau deine Stimme wünscht?","bucay":"„Der angekettete Elefant“: Ein starker Zirkuselefant bleibt an einem kleinen Pflock, weil er als Junges gelernt hat, dass er nicht loskommt.","bruecke":"Welcher alte Satz über dich ist dein „Pflock“ – und wer hat ihn eingeschlagen?","joker":false},{"nr":"04","n":4,"title":"GELASSENHEIT","titleSub":"","name":"Gelassenheit","catId":1,"catName":"Ich mit mir","catLabel":"Kategorie 1","color":"#0E7F93","tint":"rgba(14,127,147,0.10)","story":[{"t":"Als er zur Bank kam, war sein Hemd nass.","q":false},{"t":"„Das Dach tropft“, sagte er.","q":true},{"t":"„Und du?“","q":true},{"t":"„Ich habe einen Eimer daruntergestellt. Früher wäre ich sofort nervös geworden.“","q":true},{"t":"„Das klingt vernünftig.“","q":true},{"t":"Am nächsten Tag kam er wieder. Diesmal waren auch seine Schuhe nass.","q":false},{"t":"„Immer noch ruhig?“","q":true},{"t":"„Sehr.“","q":true},{"t":"„Und das Dach?“","q":true},{"t":"„Tropft noch.“","q":true},{"t":"Sie rückte ein Stück zur Seite, damit er sich setzen konnte.","q":false},{"t":"„Hast du jemanden angerufen?“","q":true},{"t":"„Ich wollte nicht in Hektik verfallen.“","q":true},{"t":"Sie sah auf seine Schuhe.","q":false},{"t":"„Ein Telefonat lässt sich erstaunlich langsam führen.“","q":true}],"sides":"Ruhe bewahren ↔ den Moment verpassen.","sideA":"Ruhe bewahren","sideB":"den Moment verpassen","dreh":"Wann bewahrt Ruhe dich vor Fehlern – und wann vor dem Handeln?","szene":"Dein Fernbus zum Konzert hat zwei Stunden Verspätung. Einlass ist um 20 Uhr. Wartest du entspannt oder suchst du sofort eine Mitfahrgelegenheit? Und was könnte dich anders entscheiden lassen?","wenn":"… es die letzte Tour der Band ist?","bucay":"„Der launenhafte König“: Ein König schwankt zwischen Hochgefühl und Verzweiflung und sucht nach etwas, das ihn in beiden Lagen hält.","bruecke":"Was hält dich in der Mitte, wenn dein Tag – oder dein Feed – nur Höhen oder nur Tiefen zeigt?","joker":false},{"nr":"05","n":5,"title":"EHRGEIZ","titleSub":"","name":"Ehrgeiz","catId":1,"catName":"Ich mit mir","catLabel":"Kategorie 1","color":"#0E7F93","tint":"rgba(14,127,147,0.10)","story":[{"t":"„Ich bin endlich oben angekommen“, sagte er.","q":true},{"t":"„Auf dem Berg?“","q":true},{"t":"Er nickte.","q":false},{"t":"„Glückwunsch. Wie war die Aussicht?“","q":true},{"t":"„Ich habe nicht hingesehen.“","q":true},{"t":"„War es neblig?“","q":true},{"t":"„Nein. Auf dem Nachbargipfel stand schon jemand.“","q":true},{"t":"„Und dann?“","q":true},{"t":"„Bin ich weiter.“","q":true},{"t":"Sie wartete.","q":false},{"t":"„Der Weg war steil“, sagte er. „Ich war völlig erschöpft.“","q":true},{"t":"„Hast du ihn erreicht?“","q":true},{"t":"„Ja.“","q":true},{"t":"„Und die Aussicht?“","q":true},{"t":"Er sah sie an.","q":false},{"t":"Dann begann er zu lachen, erst leise, dann ein wenig verlegen.","q":false},{"t":"„Ich glaube, ich muss da noch einmal hin.“","q":true}],"sides":"Dich antreiben ↔ dich unter Druck setzen.","sideA":"Dich antreiben","sideB":"dich unter Druck setzen","dreh":"Wann treibt dich ein Ziel an – und wann treibt es dich vor sich her?","szene":"Du willst diesen Sommer deinen ersten Halbmarathon laufen. Der Trainingsplan würde fast alle Wochenenden mit deinen Freunden kosten. Ziehst du ihn durch? Und was könnte dich anders entscheiden lassen?","wenn":"… deine Freunde anbieten, beim langen Lauf nebenher zu radeln?","bucay":"„Gesangswettbewerb“: Beim Sängerwettstreit der Tiere wählt jeder den schlechtesten Sänger, weil der keine Konkurrenz ist – und so gewinnt der Esel.","bruecke":"Läufst du für dein Ziel – oder für den Screenshot danach?","joker":false},{"nr":"06","n":6,"title":"BESCHEIDENHEIT","titleSub":"","name":"Bescheidenheit","catId":1,"catName":"Ich mit mir","catLabel":"Kategorie 1","color":"#0E7F93","tint":"rgba(14,127,147,0.10)","story":[{"t":"„Alle haben mein Essen gelobt“, erzählte er.","q":true},{"t":"„Wie schön.“","q":true},{"t":"„Ich habe gesagt, es sei nichts Besonderes.“","q":true},{"t":"„War es nichts Besonderes?“","q":true},{"t":"„Ich habe zwei Tage dafür gekocht.“","q":true},{"t":"„Warum hast du das nicht gesagt?“","q":true},{"t":"„Ich wollte nicht angeben.“","q":true},{"t":"Beim nächsten gemeinsamen Essen brachte die Frau Brot mit.","q":false},{"t":"„Selbst gebacken?“, fragte er.","q":true},{"t":"„Ja. Ich bin um sechs aufgestanden. Die erste Portion ist verbrannt. Diese hier ist gut geworden.“","q":true},{"t":"Er probierte ein Stück.","q":false},{"t":"„Sehr gut sogar.“","q":true},{"t":"„Danke“, sagte sie und nahm sich Butter.","q":true},{"t":"Er wartete.","q":false},{"t":"„Kommt da nichts mehr?“","q":true},{"t":"„Doch. Reichst du mir bitte das Salz?“","q":true}],"sides":"Bodenständig bleiben ↔ deinen Wert verstecken.","sideA":"Bodenständig bleiben","sideB":"deinen Wert verstecken","dreh":"Wann bleibst du bodenständig – und wann versteckst du deinen Wert?","szene":"Für die Geburtstagsüberraschung eurer Freundin bekommt die Person den Dank, die das Geschenk überreicht hat. Idee und Planung kamen von dir. Sagst du etwas? Und was könnte dich anders entscheiden lassen?","wenn":"… die Freundin sich gern auch bei dir bedanken würde?","bucay":"„Der wahre Wert des Rings“: Ein junger Mann soll einen Ring verkaufen; auf dem Markt bietet niemand viel, erst der Goldschmied erkennt den wahren Wert.","bruecke":"Wessen Daumen nach oben entscheidet, was du wert bist?","joker":false},{"nr":"07","n":7,"title":"STOLZ","titleSub":"","name":"Stolz","catId":1,"catName":"Ich mit mir","catLabel":"Kategorie 1","color":"#0E7F93","tint":"rgba(14,127,147,0.10)","story":[{"t":"Er stellte einen kleinen Hocker neben die Bank.","q":false},{"t":"„Selbst gebaut.“","q":true},{"t":"Die Frau setzte sich vorsichtig darauf. Der Hocker wackelte.","q":false},{"t":"„Ein Bein ist zu kurz“, sagte sie.","q":true},{"t":"„Das weiß ich.“","q":true},{"t":"„Soll ich dir helfen?“","q":true},{"t":"„Ich kann das allein.“","q":true},{"t":"Sie stand wieder auf.","q":false},{"t":"„Das sehe ich.“","q":true},{"t":"Er betrachtete den Hocker.","q":false},{"t":"„Du findest ihn schlecht.“","q":true},{"t":"„Nein. Ich möchte nur nicht herunterfallen.“","q":true},{"t":"Am nächsten Tag brachte er ihn wieder mit. Diesmal stand er fest.","q":false},{"t":"„Allein geschafft?“, fragte sie.","q":true},{"t":"„Mein Nachbar hat mir gezeigt, wie es geht.“","q":true},{"t":"Sie setzte sich.","q":false},{"t":"Er lächelte.","q":false},{"t":"„Selbst gebaut.“","q":true}],"sides":"Dir etwas zutrauen ↔ keine Hilfe annehmen.","sideA":"Dir etwas zutrauen","sideB":"keine Hilfe annehmen","dreh":"Wann trägt dich Stolz – und wann trennt er dich von Hilfe?","szene":"Dein Fahrrad ist kaputt und du bekommst es allein nicht hin. Dein Mitbewohner, mit dem du dich gestern gestritten hast, bietet an, es zu reparieren. Nimmst du an? Und was könnte dich anders entscheiden lassen?","wenn":"… er sich mit dem Angebot eigentlich versöhnen möchte?","bucay":"„Der König, der angebetet werden wollte“: Ein eitler König verlangt Verbeugungen; ein Bettler verweigert sie – und der König kommt zur Besinnung.","bruecke":"Wessen Bewunderung brauchst du, um dich groß zu fühlen?","joker":false},{"nr":"08","n":8,"title":"NEUGIER","titleSub":"","name":"Neugier","catId":2,"catName":"Kopf an, Kopf aus","catLabel":"Kategorie 2","color":"#C42E7C","tint":"rgba(196,46,124,0.10)","story":[{"t":"„Ich habe gestern einen wunderbaren Laden entdeckt“, sagte er.","q":true},{"t":"„Was gab es dort?“","q":true},{"t":"„Das weiß ich noch nicht.“","q":true},{"t":"„Du warst nicht drin?“","q":true},{"t":"„Doch. Aber dann hörte ich Musik aus dem Hinterhof. Dort führte eine Treppe auf eine Dachterrasse. Von dort sah ich einen Garten.“","q":true},{"t":"„Und im Garten?“","q":true},{"t":"„Eine Tür.“","q":true},{"t":"„Die hast du geöffnet.“","q":true},{"t":"„Natürlich.“","q":true},{"t":"Die Frau nickte.","q":false},{"t":"„Und der Laden?“","q":true},{"t":"Er dachte nach.","q":false},{"t":"„Da wollte ich eigentlich Brot kaufen.“","q":true},{"t":"Sie brach ihr Brötchen in zwei Hälften und reichte ihm eine.","q":false},{"t":"„Erzähl weiter. Was war hinter der Tür?“","q":true}],"sides":"Neues entdecken ↔ dich verzetteln.","sideA":"Neues entdecken","sideB":"dich verzetteln","dreh":"Wann führt dich Neugier weiter – und wann nur weg?","szene":"Du wolltest nur kurz ein Rezept nachschlagen. Eine Stunde später steckst du tief in einer Doku über Tiefseefische. Deine Gäste kommen in 30 Minuten. Schaust du weiter oder klappst du zu? Und was könnte dich anders entscheiden lassen?","wenn":"… einer deiner Gäste Meeresbiologie studiert?","bucay":"„Der vergrabene Schatz“: Ein Mann reist weit nach Prag, um einen Schatz zu suchen, und erfährt dort, dass er unter seinem eigenen Ofen liegt.","bruecke":"Was suchst du beim endlosen Scrollen, das vielleicht längst bei dir liegt?","joker":false},{"nr":"09","n":9,"title":"SKEPSIS","titleSub":"","name":"Skepsis","catId":2,"catName":"Kopf an, Kopf aus","catLabel":"Kategorie 2","color":"#C42E7C","tint":"rgba(196,46,124,0.10)","story":[{"t":"„Ein Mann hat mir Hilfe angeboten“, sagte er.","q":true},{"t":"„Und du?“","q":true},{"t":"„Ich habe abgelehnt. Man weiß ja nie.“","q":true},{"t":"„Wobei wollte er helfen?“","q":true},{"t":"„Mein Fahrrad hatte einen Platten.“","q":true},{"t":"„Hatte er Werkzeug?“","q":true},{"t":"„Ja.“","q":true},{"t":"„Sah er aus, als könnte er damit umgehen?“","q":true},{"t":"„Er kam gerade aus seiner Fahrradwerkstatt.“","q":true},{"t":"Sie sah ihn an.","q":false},{"t":"„Ich bin eben vorsichtig“, sagte er.","q":true},{"t":"„Das ist gut.“","q":true},{"t":"„Aber?“","q":true},{"t":"„Wie lange hast du nach Hause gebraucht?“","q":true},{"t":"„Zwei Stunden.“","q":true},{"t":"Die Frau nickte langsam.","q":false},{"t":"„Du hattest also ausreichend Zeit, ihn zu beobachten.“","q":true}],"sides":"Dich schützen ↔ Chancen abweisen.","sideA":"Dich schützen","sideB":"Chancen abweisen","dreh":"Wann schützt dich Prüfen – und wann verpasst du dadurch etwas?","szene":"Jemand aus einer Online-Community lädt dich ein, gemeinsam zu einem Festival zu fahren. Vieles klingt gut, einiges bleibt unklar. Sagst du ab, lässt du dich darauf ein oder prüfst du erst weiter? Und was könnte dich anders entscheiden lassen?","wenn":"… eine Freundin von dir mit dieser Person schon unterwegs war?","bucay":"„Der Lügendetektor“: Ein Mann, der sich für Napoleon hält, sagt die Wahrheit über seinen Namen – und der Detektor zeigt „Lüge“, weil er etwas anderes glaubt.","bruecke":"Prüfst du, was wahr ist – oder nur, was in den Kommentaren steht?","joker":false},{"nr":"10","n":10,"title":"OPTIMISMUS","titleSub":"","name":"Optimismus","catId":2,"catName":"Kopf an, Kopf aus","catLabel":"Kategorie 2","color":"#C42E7C","tint":"rgba(196,46,124,0.10)","story":[{"t":"„Ich habe Tomaten gepflanzt“, sagte er.","q":true},{"t":"„Auf deinem Balkon?“","q":true},{"t":"„Ja. Bald werde ich keine mehr kaufen müssen.“","q":true},{"t":"„Wie viele Pflanzen?“","q":true},{"t":"„Eine.“","q":true},{"t":"„Dann wird es ein übersichtlicher Hofladen.“","q":true},{"t":"Er lachte.","q":false},{"t":"Einige Wochen später brachte er eine kleine Tomate mit. Er legte sie zwischen sie auf die Bank.","q":false},{"t":"„Die ganze Ernte?“, fragte die Frau.","q":true},{"t":"„Bis jetzt.“","q":true},{"t":"Sie betrachteten die Tomate.","q":false},{"t":"„Bist du enttäuscht?“","q":true},{"t":"„Ein bisschen.“","q":true},{"t":"„Und nächstes Jahr?“","q":true},{"t":"„Zwei Pflanzen. Und vielleicht lese ich vorher, wie man sie pflegt.“","q":true},{"t":"Sie holte ihr Taschenmesser hervor.","q":false},{"t":"„Gut. Dieses Jahr teilen wir.“","q":true}],"sides":"Möglichkeiten sehen ↔ Aufwand unterschätzen.","sideA":"Möglichkeiten sehen","sideB":"Aufwand unterschätzen","dreh":"Wann öffnet Zuversicht Türen – und wann übersieht sie Stufen?","szene":"Deine Mitbewohner wollen an einem Wochenende die ganze WG streichen. Du hältst das für knapp. Machst du begeistert mit oder bestehst du auf einem kleineren Plan? Und was könnte dich anders entscheiden lassen?","wenn":"… die anderen die Farbe schon gekauft haben?","bucay":"„Der Portier des Freudenhauses“: Ein Portier verliert seine Stelle, weil er nicht schreiben kann, und baut aus der Not ein erfolgreiches Geschäft auf.","bruecke":"Welche Absage hat dir im Nachhinein eine Tür geöffnet?","joker":false},{"nr":"11","n":11,"title":"PESSIMISMUS","titleSub":"","name":"Pessimismus","catId":2,"catName":"Kopf an, Kopf aus","catLabel":"Kategorie 2","color":"#C42E7C","tint":"rgba(196,46,124,0.10)","story":[{"t":"Er brachte drei Regenschirme mit.","q":false},{"t":"„Es könnte regnen.“","q":true},{"t":"Die Frau sah zum blauen Himmel.","q":false},{"t":"„Für wen sind die anderen beiden?“","q":true},{"t":"„Falls einer kaputtgeht.“","q":true},{"t":"Sie gingen los. Er blickte immer wieder nach oben.","q":false},{"t":"„Da“, sagte er schließlich.","q":true},{"t":"Eine dunkle Wolke zog vor die Sonne.","q":false},{"t":"Er spannte seinen Schirm auf.","q":false},{"t":"Kurz darauf begann es tatsächlich zu regnen. Die Frau rückte unter seinen Schirm.","q":false},{"t":"„Gut, dass du vorbereitet bist.“","q":true},{"t":"Er strahlte.","q":false},{"t":"Als die Sonne wieder herauskam, blieb der Schirm offen.","q":false},{"t":"„Es könnte noch einmal anfangen“, sagte er.","q":true},{"t":"„Gewiss“, antwortete sie. „Aber im Augenblick würde ich gern den See sehen.“","q":true}],"sides":"Schwierigkeiten vorausdenken ↔ das Schlimmste erwarten.","sideA":"Schwierigkeiten vorausdenken","sideB":"das Schlimmste erwarten","dreh":"Wann bereitet dich Schwarzsehen vor – und wann verdunkelt es den Tag?","szene":"Für euer Festivalwochenende ist Dauerregen angesagt. Alle haben schon Glitzer und Zelte eingepackt. Drängst du auf einen Plan B oder gehst du das Risiko mit? Und was könnte dich anders entscheiden lassen?","wenn":"… es das letzte gemeinsame Festival vor deinem Auslandsjahr ist?","bucay":"„Verallgemeinerungsfaktor“: Demian hält sich für das Problem; ein Witz über einen Großvater zeigt, wie leicht man den falschen gemeinsamen Nenner findet.","bruecke":"Welche Schlussfolgerung über dich hast du vielleicht zu schnell gezogen?","joker":false},{"nr":"12","n":12,"title":"VERNUNFT","titleSub":"","name":"Vernunft","catId":2,"catName":"Kopf an, Kopf aus","catLabel":"Kategorie 2","color":"#C42E7C","tint":"rgba(196,46,124,0.10)","story":[{"t":"Er zeigte ihr zwei Paar Schuhe.","q":false},{"t":"„Die hier sind praktisch. Die anderen gefallen mir.“","q":true},{"t":"„Drücken die schönen?“","q":true},{"t":"„Ein wenig.“","q":true},{"t":"„Und die praktischen?“","q":true},{"t":"„Die machen mich schon beim Ansehen müde.“","q":true},{"t":"Sie betrachtete beide Paare.","q":false},{"t":"„Welche kaufst du?“","q":true},{"t":"„Die vernünftigen natürlich.“","q":true},{"t":"Am nächsten Tag kam er in seinen alten Schuhen.","q":false},{"t":"„Keine gekauft?“","q":true},{"t":"„Doch. Ein drittes Paar.“","q":true},{"t":"„Praktisch oder schön?“","q":true},{"t":"„Beides.“","q":true},{"t":"„So etwas gibt es?“","q":true},{"t":"„Offenbar. Die Verkäuferin meinte, ich hätte auch die anderen Regale ansehen dürfen.“","q":true}],"sides":"Gut für dich sorgen ↔ Wünsche zurückstellen.","sideA":"Gut für dich sorgen","sideB":"Wünsche zurückstellen","dreh":"Wann sorgt Vernunft für dich – und wann sperrt sie deine Wünsche weg?","szene":"Du hast Geld für einen neuen Laptop zurückgelegt. Jetzt gibt es günstige Flüge für die Reise, von der du seit Jahren träumst. Wofür entscheidest du dich? Und was könnte dich anders entscheiden lassen?","wenn":"… deine beste Freundin genau dann auch frei hat?","bucay":"„Zwei Nummern kleiner“: Ein Mann trägt absichtlich zu enge Schuhe, weil das Ausziehen am Abend sein einziges Vergnügen ist.","bruecke":"Welche „vernünftige“ Last trägst du nur, um sie abends abzustellen?","joker":false},{"nr":"13","n":13,"title":"BAUCHGEFÜHL","titleSub":"","name":"Bauchgefühl","catId":2,"catName":"Kopf an, Kopf aus","catLabel":"Kategorie 2","color":"#C42E7C","tint":"rgba(196,46,124,0.10)","story":[{"t":"„Ich habe die Wohnung abgesagt“, sagte er.","q":true},{"t":"„Warum?“","q":true},{"t":"„Ein ungutes Gefühl.“","q":true},{"t":"„Was hat dir nicht gefallen?“","q":true},{"t":"„Ich weiß es nicht. Sie war hell. Günstig. Gut gelegen.“","q":true},{"t":"Die Frau wartete.","q":false},{"t":"„Der Vermieter hat ständig für mich geantwortet“, sagte er schließlich. „Wenn ich etwas fragen wollte, erklärte er mir, dass ich mir keine Sorgen machen müsse.“","q":true},{"t":"„Und das hat dir Sorgen gemacht.“","q":true},{"t":"Er nickte.","q":false},{"t":"„Vielleicht war ich ungerecht.“","q":true},{"t":"„Vielleicht.“","q":true},{"t":"„Du meinst, ich sollte noch einmal hin?“","q":true},{"t":"„Nur, wenn du möchtest.“","q":true},{"t":"Er atmete aus.","q":false},{"t":"„Merkwürdig“, sagte er. „Allein das klingt schon angenehmer.“","q":true}],"sides":"Innere Signale ernst nehmen ↔ dich von einem Eindruck lenken lassen.","sideA":"Innere Signale ernst nehmen","sideB":"dich von einem Eindruck lenken lassen","dreh":"Wann ist ein Gefühl ein Hinweis – und wann nur eine Färbung?","szene":"Ein Date ist auf dem Papier perfekt: gleiche Musik, gleicher Humor, gute Gespräche. Trotzdem fühlt sich etwas komisch an. Triffst du die Person ein zweites Mal? Und was könnte dich anders entscheiden lassen?","wenn":"… die Person beim ersten Date einfach sehr nervös war?","bucay":"„Der liebende Blick“: Ein König sieht in denselben Taten einer Frau erst Liebe und später Fehler – geändert hat sich nur sein Blick.","bruecke":"Spürt dein Bauch die Person – oder die Brille, durch die du gerade schaust?","joker":false},{"nr":"14","n":14,"title":"GRÜBELN","titleSub":"","name":"Grübeln","catId":2,"catName":"Kopf an, Kopf aus","catLabel":"Kategorie 2","color":"#C42E7C","tint":"rgba(196,46,124,0.10)","story":[{"t":"„Ich hätte etwas anderes sagen müssen.“","q":true},{"t":"„Wann?“","q":true},{"t":"„Am Dienstag.“","q":true},{"t":"„Heute ist Samstag.“","q":true},{"t":"„Ich weiß. Inzwischen habe ich die perfekte Antwort.“","q":true},{"t":"„Möchtest du sie mir sagen?“","q":true},{"t":"Er richtete sich auf und hielt eine kurze, eindrucksvolle Rede.","q":false},{"t":"Die Frau nickte.","q":false},{"t":"„Sehr gut.“","q":true},{"t":"Er entspannte sich.","q":false},{"t":"Dann zog er die Stirn kraus.","q":false},{"t":"„Obwohl … wenn er darauf geantwortet hätte, dass …“","q":true},{"t":"Sie hob eine Hand.","q":false},{"t":"„Wollen wir ihn einladen?“","q":true},{"t":"„Wen?“","q":true},{"t":"„Den Mann vom Dienstag. Er verbringt offenbar ohnehin das ganze Wochenende mit uns.“","q":true}],"sides":"Erfahrungen durchdenken ↔ gedanklich festhängen.","sideA":"Erfahrungen durchdenken","sideB":"gedanklich festhängen","dreh":"Wann hilft Nachdenken – und wann hält es dich fest?","szene":"Du hast einer Freundin eine lange Sprachnachricht geschickt. Sie antwortet nur mit einem Daumen. Seitdem spielst du die Nachricht im Kopf ab. Fragst du nach, denkst du weiter darüber nach oder lässt du es bewusst ruhen? Und was könnte dich anders entscheiden lassen?","wenn":"… sie die Nachricht im Bus gehört und danach einfach vergessen hat?","bucay":"„Die Flussüberquerung“: Ein Mönch trägt eine Frau über den Fluss und setzt sie ab; sein Begleiter trägt sie in Gedanken noch stundenlang mit.","bruecke":"Welche Nachricht hast du längst abgeschickt – und trägst sie trotzdem noch mit dir herum?","joker":false},{"nr":"15","n":15,"title":"EHRLICHKEIT","titleSub":"","name":"Ehrlichkeit","catId":3,"catName":"Zusammen ist man weniger allein","catLabel":"Kategorie 3","color":"#1FAFC7","tint":"rgba(31,175,199,0.13)","story":[{"t":"„Ich habe ihr nur die Wahrheit gesagt.“","q":true},{"t":"„Welche?“","q":true},{"t":"„Dass ihre Suppe schrecklich schmeckt.“","q":true},{"t":"„Hat sie gefragt?“","q":true},{"t":"„Nein.“","q":true},{"t":"„War sie ungenießbar?“","q":true},{"t":"„Zu salzig.“","q":true},{"t":"Die Frau goss ihm Tee ein.","q":false},{"t":"Er nahm einen Schluck und verzog das Gesicht.","q":false},{"t":"„Der ist bitter.“","q":true},{"t":"„Ja.“","q":true},{"t":"„Warum hast du ihn so lange ziehen lassen?“","q":true},{"t":"„Ich war mit deiner Geschichte beschäftigt.“","q":true},{"t":"Er stellte die Tasse ab.","q":false},{"t":"„Du könntest etwas Wasser dazugießen.“","q":true},{"t":"Sie nahm den Kessel.","q":false},{"t":"„Bei der Suppe wäre das vielleicht auch ein guter Anfang gewesen.“","q":true}],"sides":"Klarheit schaffen ↔ jemanden verletzen.","sideA":"Klarheit schaffen","sideB":"jemanden verletzen","dreh":"Wann schafft Wahrheit Klarheit – und wann nur Schaden?","szene":"Dein bester Freund zeigt dir stolz sein neues Tattoo. Dir gefällt es nicht. Er fragt nicht nach deiner Meinung. Sagst du trotzdem etwas? Und was könnte dich anders entscheiden lassen?","wenn":"… er nächste Woche ein zweites im gleichen Stil stechen lassen will?","bucay":"„Der Wahrheitsladen“: In einem Laden kann man die ganze Wahrheit kaufen – der Preis ist, dass man danach nie mehr Ruhe hat.","bruecke":"Welchen Preis zahlst du für die ganze Wahrheit – und wer zahlt mit?","joker":false},{"nr":"16","n":16,"title":"HÖFLICHKEIT","titleSub":"","name":"Höflichkeit","catId":3,"catName":"Zusammen ist man weniger allein","catLabel":"Kategorie 3","color":"#1FAFC7","tint":"rgba(31,175,199,0.13)","story":[{"t":"„Ich kann ihren Kuchen nicht mehr sehen“, sagte er.","q":true},{"t":"„Dann iss ihn nicht.“","q":true},{"t":"„Sie backt ihn extra für mich.“","q":true},{"t":"„Warum?“","q":true},{"t":"„Weil ich beim ersten Mal gesagt habe, wie gern ich ihn mag.“","q":true},{"t":"„Magst du ihn?“","q":true},{"t":"„Nein.“","q":true},{"t":"Die Frau schwieg.","q":false},{"t":"„Was hätte ich denn sagen sollen?“","q":true},{"t":"„Vielleicht, dass du dich über ihren Besuch freust.“","q":true},{"t":"In der nächsten Woche kam er lächelnd zur Bank.","q":false},{"t":"„Und?“, fragte sie.","q":true},{"t":"„Wir sind spazieren gegangen.“","q":true},{"t":"„Ohne Kuchen?“","q":true},{"t":"„Ohne Kuchen.“","q":true},{"t":"Er lehnte sich zurück.","q":false},{"t":"„Sie war erleichtert. Sie backt gar nicht gern.“","q":true}],"sides":"Gefühle schonen ↔ eigene Bedürfnisse verschweigen.","sideA":"Gefühle schonen","sideB":"eigene Bedürfnisse verschweigen","dreh":"Wann schont Höflichkeit andere – und wann verschluckst du dich selbst?","szene":"Bei den Eltern deines Partners gibt es zum dritten Mal Nachschlag. Du bist längst satt. Wie reagierst du? Und was könnte dich anders entscheiden lassen?","wenn":"… die Mutter sich insgeheim über ein ehrliches Nein freuen würde?","bucay":"„Der Bumerangziegel“: Zurückgehaltene Wut ist wie ein Ziegel, den man nicht wirft – er fliegt zurück und trifft einen selbst.","bruecke":"Wohin fliegt das, was du aus Höflichkeit runterschluckst?","joker":false},{"nr":"17","n":17,"title":"HILFSBEREITSCHAFT","titleSub":"","name":"Hilfsbereitschaft","catId":3,"catName":"Zusammen ist man weniger allein","catLabel":"Kategorie 3","color":"#1FAFC7","tint":"rgba(31,175,199,0.13)","story":[{"t":"Er setzte sich mit einem leisen Stöhnen.","q":false},{"t":"„Wieder beim Umzug geholfen?“","q":true},{"t":"„Ja.“","q":true},{"t":"„Du hattest doch Rückenschmerzen.“","q":true},{"t":"„Sie brauchten mich.“","q":true},{"t":"„Für die schweren Möbel?“","q":true},{"t":"„Vor allem.“","q":true},{"t":"Die Frau reichte ihm ihre Tasche.","q":false},{"t":"Er griff danach und zuckte zusammen.","q":false},{"t":"Sie nahm sie zurück.","q":false},{"t":"„Was ist drin?“, fragte er.","q":true},{"t":"„Ein Buch.“","q":true},{"t":"Er sah sie beleidigt an.","q":false},{"t":"„Das war gemein.“","q":true},{"t":"„Ein bisschen.“","q":true},{"t":"Eine Weile später zog er sein Telefon hervor.","q":false},{"t":"„Wen rufst du an?“","q":true},{"t":"„Die anderen. Die Kisten können sie morgen selbst tragen.“","q":true},{"t":"„Und du?“","q":true},{"t":"„Ich mache Kaffee. Im Sitzen.“","q":true}],"sides":"Für andere da sein ↔ über deine Grenzen gehen.","sideA":"Für andere da sein","sideB":"über deine Grenzen gehen","dreh":"Wann ist Helfen ein Geschenk – und wann ein Verlust für dich?","szene":"Ein Freund braucht kurzfristig Hilfe beim Umzug in den vierten Stock ohne Aufzug. Du hattest dir nach einer anstrengenden Woche einen freien Samstag versprochen. Was bietest du ihm an? Und was könnte dich anders entscheiden lassen?","wenn":"… du die einzige Person bist, die helfen könnte?","bucay":"„Auf der Suche nach Buddha“: Ein Mönch verpasst Buddha zwanzig Jahre lang, weil er immer wieder anderen hilft – und findet ihn genau dabei.","bruecke":"Was findest du beim Helfen – und was verpasst du?","joker":false},{"nr":"18","n":18,"title":"EMPATHIE","titleSub":"","name":"Empathie","catId":3,"catName":"Zusammen ist man weniger allein","catLabel":"Kategorie 3","color":"#1FAFC7","tint":"rgba(31,175,199,0.13)","story":[{"t":"„Sie kam wieder zu spät“, sagte er.","q":true},{"t":"„Hatte sie einen Grund?“","q":true},{"t":"„Natürlich. Sie hat gerade viel um die Ohren.“","q":true},{"t":"„Und du?“","q":true},{"t":"„Ich verstehe sie.“","q":true},{"t":"Die Frau nickte.","q":false},{"t":"Er rieb seine kalten Hände.","q":false},{"t":"„Wie lange hast du gewartet?“","q":true},{"t":"„Eine Stunde.“","q":true},{"t":"„Draußen?“","q":true},{"t":"„Sie hätte mich sonst nicht gefunden.“","q":true},{"t":"Die Frau rückte näher.","q":false},{"t":"„Was hättest du gebraucht?“","q":true},{"t":"Er wollte sofort antworten, hielt aber inne.","q":false},{"t":"„Eine Nachricht“, sagte er schließlich. „Und einen warmen Ort.“","q":true},{"t":"„Kannst du ihr das sagen?“","q":true},{"t":"Er nickte.","q":false},{"t":"„Vermutlich versteht sie mich auch.“","q":true}],"sides":"Mitfühlen ↔ dich selbst vergessen.","sideA":"Mitfühlen","sideB":"dich selbst vergessen","dreh":"Wann verbindet Mitgefühl – und wann vergisst es dich selbst?","szene":"Eine Freundin sagt euer Treffen zum dritten Mal eine Stunde vorher per Nachricht ab. Du weißt, dass sie gerade viel durchmacht. Sprichst du deine Enttäuschung an? Und was könnte dich anders entscheiden lassen?","wenn":"… sie sich längst eine ehrliche Reaktion von dir wünscht?","bucay":"„Das Huhn und die kleinen Entlein“: Eine Henne zieht Entlein groß und fürchtet um sie, als sie ins Wasser gehen – jeder sieht die Welt aus der eigenen Lage.","bruecke":"Fühlst du dich in den anderen ein – oder in dich, an seiner Stelle?","joker":false},{"nr":"19","n":19,"title":"VERTRAUEN","titleSub":"","name":"Vertrauen","catId":3,"catName":"Zusammen ist man weniger allein","catLabel":"Kategorie 3","color":"#1FAFC7","tint":"rgba(31,175,199,0.13)","story":[{"t":"„Ich habe ihm meinen Schlüssel gegeben.“","q":true},{"t":"„Zum Blumengießen?“","q":true},{"t":"„Ja. Jetzt fehlt mein Lieblingsjoghurt.“","q":true},{"t":"„Wie geht es den Pflanzen?“","q":true},{"t":"„Ausgezeichnet.“","q":true},{"t":"„Hast du ihn gefragt?“","q":true},{"t":"„Er meinte, er hätte Hunger gehabt.“","q":true},{"t":"Die Frau lächelte.","q":false},{"t":"„Du nicht?“","q":true},{"t":"„Ich überlege, ob ich den Schlüssel zurückverlange.“","q":true},{"t":"„Wegen des Joghurts?“","q":true},{"t":"„Wegen des Prinzips.“","q":true},{"t":"Sie nickte.","q":false},{"t":"Am nächsten Tag brachte er zwei Joghurts mit.","q":false},{"t":"„Alles geklärt?“","q":true},{"t":"„Ja. Die Pflanzen darf er weiter gießen.“","q":true},{"t":"„Und der Kühlschrank?“","q":true},{"t":"„Dafür braucht er jetzt eine eigene Genehmigung.“","q":true}],"sides":"Nähe ermöglichen ↔ dich verletzlich machen.","sideA":"Nähe ermöglichen","sideB":"dich verletzlich machen","dreh":"Wann ist Vertrauen ein Geschenk – und wann glaubst du nur, was du glauben willst?","szene":"Eine Freundin möchte sich deine Kamera für ihren Urlaub ausleihen. Beim letzten Mal kam das Objektiv zerkratzt zurück. Leihst du sie ihr noch einmal? Und was könnte dich anders entscheiden lassen?","wenn":"… sie den Kratzer damals heimlich reparieren lassen wollte?","bucay":"„Die Exekution“: Ein Tyrann glaubt eine List, weil er sie glauben will – und das kostet ihn alles.","bruecke":"Vertraust du dem Menschen – oder deinem Wunsch, dass es stimmt?","joker":false},{"nr":"20","n":20,"title":"HARMONIEBEDÜRFNIS","titleSub":"","name":"Harmoniebedürfnis","catId":3,"catName":"Zusammen ist man weniger allein","catLabel":"Kategorie 3","color":"#1FAFC7","tint":"rgba(31,175,199,0.13)","story":[{"t":"„Wir konnten uns nicht auf ein Restaurant einigen.“","q":true},{"t":"„Was wolltest du essen?“","q":true},{"t":"„Das war mir nicht wichtig.“","q":true},{"t":"„Und was wolltest du nicht essen?“","q":true},{"t":"„Sushi.“","q":true},{"t":"„Wo wart ihr?“","q":true},{"t":"Er sah sie an.","q":false},{"t":"„Beim Sushi.“","q":true},{"t":"„Hast du etwas gesagt?“","q":true},{"t":"„Ich wollte die Stimmung nicht verderben.“","q":true},{"t":"„Wie war die Stimmung?“","q":true},{"t":"„Ich war still. Die anderen fragten ständig, ob etwas sei.“","q":true},{"t":"Sie nickte.","q":false},{"t":"„Und?“","q":true},{"t":"„Ich sagte: nichts.“","q":true},{"t":"Die Frau griff nach ihrer Tasche.","q":false},{"t":"„Komm.“","q":true},{"t":"„Wohin?“","q":true},{"t":"„Essen.“","q":true},{"t":"Er zögerte.","q":false},{"t":"Dann sagte er: „Bitte kein Sushi.“","q":false},{"t":"„Siehst du“, antwortete sie. „Noch mögen wir uns.“","q":true}],"sides":"Streit vermeiden ↔ Klarheit verhindern.","sideA":"Streit vermeiden","sideB":"Klarheit verhindern","dreh":"Wann hält Harmonie euch zusammen – und wann hält sie dich zurück?","szene":"Alle in eurer Gruppe wollen am Samstag in den Escape Room. Du hast keine Lust darauf. Sagst du es, machst du mit oder schlägst du etwas anderes vor? Und was könnte dich anders entscheiden lassen?","wenn":"… die anderen nur zugestimmt haben, weil sie dachten, du willst es?","bucay":"„Linsen“: Ein Höfling rät Diogenes, dem Kaiser zu schmeicheln, dann müsse er keine Linsen essen; Diogenes dreht den Satz um.","bruecke":"Wie oft würdest du „passt schon“ sagen, um nicht Nein sagen zu müssen?","joker":false},{"nr":"21","n":21,"title":"LOYALITÄT","titleSub":"","name":"Loyalität","catId":3,"catName":"Zusammen ist man weniger allein","catLabel":"Kategorie 3","color":"#1FAFC7","tint":"rgba(31,175,199,0.13)","story":[{"t":"„Ich halte zu meinem Freund“, sagte er.","q":true},{"t":"„Das ist schön.“","q":true},{"t":"„Auch wenn er Fehler macht.“","q":true},{"t":"„Das ist Freundschaft.“","q":true},{"t":"„Ich habe seinem Chef gesagt, er sei krank.“","q":true},{"t":"„War er krank?“","q":true},{"t":"„Nein.“","q":true},{"t":"„Wo war er?“","q":true},{"t":"„Am See.“","q":true},{"t":"Die Frau betrachtete ihn.","q":false},{"t":"„Und wo warst du?“","q":true},{"t":"„Bei seiner Arbeit. Ich habe seine Schicht übernommen.“","q":true},{"t":"Eine Weile sagte keiner etwas.","q":false},{"t":"„Ich will ihn nicht im Stich lassen“, sagte er schließlich.","q":true},{"t":"„Dann sag ihm, was du von ihm brauchst.“","q":true},{"t":"Er seufzte.","q":false},{"t":"„Er wird sich ärgern.“","q":true},{"t":"„Möglich.“","q":true},{"t":"„Das halte ich aus.“","q":true}],"sides":"Rückhalt geben ↔ zu viel mittragen.","sideA":"Rückhalt geben","sideB":"zu viel mittragen","dreh":"Wann ist Treue ein Halt – und wann eine Fessel?","szene":"Dein Mitbewohner bittet dich, seiner Freundin zu sagen, er sei gestern Abend zu Hause gewesen. Du magst beide. Was antwortest du? Und was könnte dich anders entscheiden lassen?","wenn":"… sie dich erst letzte Woche um deine ehrliche Meinung zu ihm gebeten hat?","bucay":"„Besitzansprüche“: Ein Mann schleppt einen Berg Gold mit sich herum – bis die Frage auftaucht, wer hier eigentlich wen besitzt.","bruecke":"Gehört dir die Bindung – oder gehörst du ihr?","joker":false},{"nr":"22","n":22,"title":"SPONTANEITÄT","titleSub":"","name":"Spontaneität","catId":4,"catName":"Machen, lassen, weitermachen","catLabel":"Kategorie 4","color":"#E8489A","tint":"rgba(232,72,154,0.11)","story":[{"t":"„Ich fahre ans Meer“, sagte er.","q":true},{"t":"„Wann?“","q":true},{"t":"„Jetzt.“","q":true},{"t":"„Wunderbar.“","q":true},{"t":"Er kam eine Stunde später zurück.","q":false},{"t":"„Schon wieder da?“","q":true},{"t":"„Ausweis vergessen.“","q":true},{"t":"Er verschwand und kam erneut.","q":false},{"t":"„Was diesmal?“","q":true},{"t":"„Der Schlüssel für die Ferienwohnung.“","q":true},{"t":"Beim dritten Mal setzte er sich neben sie.","q":false},{"t":"„Zug weg?“","q":true},{"t":"Er nickte.","q":false},{"t":"Sie reichte ihm eine Aprikose.","q":false},{"t":"„Morgen fährt wieder einer.“","q":true},{"t":"Er biss hinein.","q":false},{"t":"„Dann plane ich heute eben ein bisschen.“","q":true},{"t":"„Und das Meer?“","q":true},{"t":"„Das wird hoffentlich noch da sein.“","q":true}],"sides":"Gelegenheiten nutzen ↔ Wichtiges übersehen.","sideA":"Gelegenheiten nutzen","sideB":"Wichtiges übersehen","dreh":"Wann ist ein spontanes Ja Lebenslust – und wann Kurzschluss?","szene":"Um 22 Uhr fragen dich Freunde, ob du morgen früh mit nach Lissabon fliegst. Die Tickets sind billig, einiges ist noch ungeklärt. Buchst du – oder lässt du die Gelegenheit verstreichen? Und was könnte dich anders entscheiden lassen?","wenn":"… dort eine alte Freundin wohnt, die du seit Jahren nicht gesehen hast?","bucay":"„Der Zentaur“: Ein Zentaur, halb Mensch, halb Pferd, kann sich zwischen seinen Hälften nie entscheiden – und das Nichtentscheiden wird zur schlechtesten Wahl.","bruecke":"Was kostet es dich, wenn du gar nicht entscheidest?","joker":false},{"nr":"23","n":23,"title":"PLANUNG","titleSub":"","name":"Planung","catId":4,"catName":"Machen, lassen, weitermachen","catLabel":"Kategorie 4","color":"#E8489A","tint":"rgba(232,72,154,0.11)","story":[{"t":"Er breitete einen großen Plan auf der Bank aus.","q":false},{"t":"„Unser Urlaub. Alles organisiert.“","q":true},{"t":"Die Frau beugte sich darüber.","q":false},{"t":"„Dienstag, fünfzehn Uhr: entspannen.“","q":true},{"t":"„Genau.“","q":true},{"t":"„Bis wann?“","q":true},{"t":"„Fünfzehn Uhr vierzig. Dann geht es ins Museum.“","q":true},{"t":"Sie nickte beeindruckt.","q":false},{"t":"„Und wenn du länger entspannen möchtest?“","q":true},{"t":"„Dann verschiebt sich alles.“","q":true},{"t":"Ein Windstoß erfasste den Plan. Beide liefen hinterher.","q":false},{"t":"Als sie ihn wiederhatten, waren die Ränder eingerissen.","q":false},{"t":"Er lachte außer Atem.","q":false},{"t":"Die Frau sah auf ihre Uhr.","q":false},{"t":"„Dafür war jetzt vermutlich keine Zeit vorgesehen.“","q":true},{"t":"Er faltete den Plan zusammen.","q":false},{"t":"„Doch“, sagte er. „Ab jetzt schon.“","q":true}],"sides":"Orientierung schaffen ↔ wenig Spielraum lassen.","sideA":"Orientierung schaffen","sideB":"wenig Spielraum lassen","dreh":"Wann gibt ein Plan Halt – und wann wird er zum Ritual?","szene":"Auf eurem Interrail-Trip lädt euch eine Einheimische spontan zu einem Familienfest ein. Dafür müsstest du den lange geplanten Tagesausflug streichen. Was machst du? Und was könnte dich anders entscheiden lassen?","wenn":"… der Ausflugsort nächstes Jahr geschlossen wird?","bucay":"„Die Katze des Aschrams“: Eine Katze wird während der Meditation angebunden; Jahre später gilt das Anbinden als heilige Regel, obwohl der Grund längst verschwunden ist.","bruecke":"Welcher deiner Pläne hat seinen Grund überlebt?","joker":false},{"nr":"24","n":24,"title":"DISZIPLIN","titleSub":"","name":"Disziplin","catId":4,"catName":"Machen, lassen, weitermachen","catLabel":"Kategorie 4","color":"#E8489A","tint":"rgba(232,72,154,0.11)","story":[{"t":"„Ich habe seit hundert Tagen keinen Lauf ausgelassen.“","q":true},{"t":"„Auch gestern nicht?“","q":true},{"t":"„Auch gestern nicht.“","q":true},{"t":"„Du hattest Fieber.“","q":true},{"t":"„Ich wollte meine Serie nicht unterbrechen.“","q":true},{"t":"Die Frau nahm einen kleinen Kalender aus ihrer Tasche.","q":false},{"t":"„Ich gieße seit hundert Tagen meine Pflanze.“","q":true},{"t":"„Sehr konsequent.“","q":true},{"t":"„Gestern war die Erde noch nass.“","q":true},{"t":"„Dann hast du hoffentlich nicht gegossen.“","q":true},{"t":"Sie sah ihn an.","q":false},{"t":"Er zog die Augenbrauen zusammen.","q":false},{"t":"„Menschen sind keine Pflanzen.“","q":true},{"t":"„Gewiss nicht.“","q":true},{"t":"Am nächsten Morgen blieb er im Bett.","q":false},{"t":"In seinen Kalender schrieb er: „Tag 101. Trainiert, rechtzeitig aufzuhören.“","q":false}],"sides":"Dranbleiben ↔ eigene Grenzen übergehen.","sideA":"Dranbleiben","sideB":"eigene Grenzen übergehen","dreh":"Wann trägt Disziplin dich – und wann treibt sie dich nur an?","szene":"Deine Lernserie in der Sprach-App läuft seit 200 Tagen. Heute bist du erkältet und völlig erledigt. Machst du deine Lektion trotzdem? Und was könnte dich anders entscheiden lassen?","wenn":"… niemand außer dir diese Serie jemals sehen wird?","bucay":"„Der beharrliche Holzfäller“: Ein Holzfäller schlägt jeden Tag weniger Bäume, weil er sich nie die Zeit nimmt, seine Axt zu schärfen.","bruecke":"Wann hast du deine „Axt“ zuletzt geschärft – statt nur weiterzuhacken?","joker":false},{"nr":"25","n":25,"title":"FLEXIBILITÄT","titleSub":"","name":"Flexibilität","catId":4,"catName":"Machen, lassen, weitermachen","catLabel":"Kategorie 4","color":"#E8489A","tint":"rgba(232,72,154,0.11)","story":[{"t":"„Ich bin unkompliziert“, sagte er.","q":true},{"t":"„Das stimmt.“","q":true},{"t":"„Wir haben den Ausflug dreimal verschoben. Für mich war das in Ordnung.“","q":true},{"t":"„Und jetzt?“","q":true},{"t":"„Jetzt fahren wir nicht mehr an den See, sondern ins Einkaufszentrum.“","q":true},{"t":"„Auch in Ordnung?“","q":true},{"t":"Er zuckte mit den Schultern.","q":false},{"t":"„Die anderen wollen es.“","q":true},{"t":"Die Frau stand auf.","q":false},{"t":"„Dann komm. Wir gehen auch dorthin.“","q":true},{"t":"Er verzog das Gesicht.","q":false},{"t":"Sie setzte sich wieder.","q":false},{"t":"„Ah“, sagte sie. „Da bist du ja.“","q":true}],"sides":"Beweglich bleiben ↔ dich selbst zurücknehmen.","sideA":"Beweglich bleiben","sideB":"dich selbst zurücknehmen","dreh":"Wann ist Anpassen klug – und wann verlierst du dich dabei?","szene":"Die Pläne für euren Freundesabend werden im Gruppenchat zum dritten Mal geändert. Du könntest dich anpassen, aber dein Wunsch fällt wieder weg. Gehst du mit? Und was könnte dich anders entscheiden lassen?","wenn":"… es den anderen genauso geht wie dir?","bucay":"„Die Triebe des Ombú-Baums“: Um einen alten Baum und seine jungen Triebe entsteht Streit; ein Alter zeigt, dass beides zum selben Kreislauf gehört.","bruecke":"Was darf bei dir alt bleiben – und was will neu austreiben?","joker":false},{"nr":"26","n":26,"title":"BEHARRLICHKEIT","titleSub":"","name":"Beharrlichkeit","catId":4,"catName":"Machen, lassen, weitermachen","catLabel":"Kategorie 4","color":"#E8489A","tint":"rgba(232,72,154,0.11)","story":[{"t":"„Ich habe es endlich geschafft“, sagte er.","q":true},{"t":"„Was?“","q":true},{"t":"„Der Kundenservice erstattet mir das Geld.“","q":true},{"t":"„Nach wie vielen Anrufen?“","q":true},{"t":"„Sieben.“","q":true},{"t":"„Gut, dass du drangeblieben bist.“","q":true},{"t":"Er nickte zufrieden.","q":false},{"t":"Dann zeigte er auf sein Telefon.","q":false},{"t":"„Außerdem habe ich meiner ehemaligen Freundin wieder geschrieben.“","q":true},{"t":"„Wie oft?“","q":true},{"t":"„Sieben Mal.“","q":true},{"t":"„Was hat sie geantwortet?“","q":true},{"t":"„Dass ich aufhören soll.“","q":true},{"t":"Die Frau schwieg.","q":false},{"t":"Er sah erst sie an, dann das Telefon.","q":false},{"t":"Langsam steckte er es weg.","q":false},{"t":"„Die Erstattung“, sagte er nach einer Weile, „war immerhin ein Erfolg.“","q":true}],"sides":"Nicht aufgeben ↔ zu lange festhalten.","sideA":"Nicht aufgeben","sideB":"zu lange festhalten","dreh":"Wann führt Durchhalten ans Ziel – und wann nur tiefer in den Topf?","szene":"Seit Monaten postest du deine Zeichnungen online. Es gibt kleine Fortschritte, aber kaum Reichweite. Machst du weiter, änderst du den Weg oder hörst du auf? Und was könnte dich anders entscheiden lassen?","wenn":"… ein kleiner Kurswechsel genau die richtigen Leute erreichen würde?","bucay":"„Die Fröschlein in der Sahne“: Zwei Frösche fallen in Sahne; einer gibt auf, der andere strampelt weiter, bis Butter entsteht und er hinausspringt.","bruecke":"Strampelst du gerade – oder rührst du nur im Kreis?","joker":false},{"nr":"27","n":27,"title":"UNGEDULD","titleSub":"","name":"Ungeduld","catId":4,"catName":"Machen, lassen, weitermachen","catLabel":"Kategorie 4","color":"#E8489A","tint":"rgba(232,72,154,0.11)","story":[{"t":"„Ich habe die Schlange gewechselt.“","q":true},{"t":"„Und?“","q":true},{"t":"„Die andere war schneller.“","q":true},{"t":"„Dann war es richtig.“","q":true},{"t":"„Bis die Kasse geschlossen wurde.“","q":true},{"t":"„Was hast du gemacht?“","q":true},{"t":"„Bin zurück.“","q":true},{"t":"„An deinen alten Platz?“","q":true},{"t":"„Ganz nach hinten.“","q":true},{"t":"Die Frau nickte mitfühlend.","q":false},{"t":"„Das Schlimmste war“, sagte er, „dass alle lächelten.“","q":true},{"t":"„Vielleicht kannten sie die Geschichte.“","q":true},{"t":"„Welche Geschichte?“","q":true},{"t":"Sie deutete zum Bäcker gegenüber.","q":false},{"t":"Dort wechselte gerade ein Mann die Schlange.","q":false},{"t":"Beide sahen ihm nach.","q":false},{"t":"„Ich könnte ihn warnen“, sagte er.","q":true},{"t":"„Vielleicht“, antwortete sie. „Aber dort wird gerade eine neue Kasse geöffnet.“","q":true}],"sides":"Veränderung anstoßen ↔ vorschnell handeln.","sideA":"Veränderung anstoßen","sideB":"vorschnell handeln","dreh":"Wann bringt Ungeduld Bewegung – und wann zieht sie zu früh Schlüsse?","szene":"Du hast nach einem schönen Date geschrieben. Die Nachricht ist seit zwei Tagen gelesen, aber unbeantwortet. Schreibst du noch einmal oder wartest du? Und was könnte dich anders entscheiden lassen?","wenn":"… die Person dir gerade eine lange, ehrliche Antwort tippt?","bucay":"„Der Mann, der glaubte, er sei tot“: Ein Mann ist überzeugt, gestorben zu sein, legt sich hin und bleibt reglos liegen – mit üblen Folgen.","bruecke":"Wo hast du dich schon für erledigt erklärt, bevor es entschieden war?","joker":false},{"nr":"28","n":28,"title":"BEQUEMLICHKEIT","titleSub":"","name":"Bequemlichkeit","catId":4,"catName":"Machen, lassen, weitermachen","catLabel":"Kategorie 4","color":"#E8489A","tint":"rgba(232,72,154,0.11)","story":[{"t":"„Ich habe mir alles liefern lassen“, sagte er.","q":true},{"t":"„Dann hattest du einen freien Nachmittag.“","q":true},{"t":"„Fast. Ich musste erreichbar sein.“","q":true},{"t":"„Was hast du gemacht?“","q":true},{"t":"„Auf die Lieferung gewartet.“","q":true},{"t":"„Konntest du lesen?“","q":true},{"t":"„Ich habe ständig auf die Karte geschaut. Der Fahrer war erst ganz nah, dann wieder weit weg.“","q":true},{"t":"„Spannend.“","q":true},{"t":"„Sehr.“","q":true},{"t":"Die Frau nickte zum Laden auf der anderen Straßenseite.","q":false},{"t":"„Dort gibt es auch Brot.“","q":true},{"t":"„Ich wollte mir den Weg sparen.“","q":true},{"t":"In diesem Moment klingelte sein Telefon.","q":false},{"t":"Er sprang auf.","q":false},{"t":"„Ich muss los. Der Fahrer findet das Haus nicht.“","q":true}],"sides":"Aufwand sparen ↔ in Passivität rutschen.","sideA":"Aufwand sparen","sideB":"in Passivität rutschen","dreh":"Wann ist Bequemlichkeit kluge Schonung – und wann ein teurer Umweg?","szene":"Du könntest dir heute wieder Essen liefern lassen. Selbst einkaufen und kochen wäre günstiger, würde aber deinen freien Abend beanspruchen. Was wählst du? Und was könnte dich anders entscheiden lassen?","wenn":"… heute der einzige Abend der Woche ist, an dem du ganz für dich bist?","bucay":"„Wegen eines Krugs Wein“: Für ein Fest soll jeder Wein bringen; jeder denkt, sein Krug Wasser falle nicht auf – am Ende ist das Fass voller Wasser.","bruecke":"Wo verlässt du dich darauf, dass in der WG schon jemand anderes den „Wein“ bringt?","joker":false},{"nr":"29","n":29,"title":"SPARSAMKEIT","titleSub":"","name":"Sparsamkeit","catId":5,"catName":"Meins, deins, unseres","catLabel":"Kategorie 5","color":"#18202E","tint":"rgba(24,32,46,0.08)","story":[{"t":"Er stellte eine große Packung Kaffee auf die Bank.","q":false},{"t":"„Drei Euro gespart.“","q":true},{"t":"„Gut.“","q":true},{"t":"„Dafür musste ich ans andere Ende der Stadt.“","q":true},{"t":"„Wie bist du gefahren?“","q":true},{"t":"„Mit dem Auto.“","q":true},{"t":"Die Frau nickte.","q":false},{"t":"Er zog einen zerknitterten Zettel aus der Tasche.","q":false},{"t":"„Und ein Parkticket habe ich bekommen.“","q":true},{"t":"„Wie viel?“","q":true},{"t":"Er nannte den Betrag.","q":false},{"t":"Sie schwiegen.","q":false},{"t":"Dann strich er über die Kaffeepackung.","q":false},{"t":"„Wenigstens reicht er lange.“","q":true},{"t":"„Das hoffe ich“, sagte sie. „Jetzt musst du ihn wohl eine Weile schwarz trinken.“","q":true}],"sides":"Ressourcen schonen ↔ am falschen Ende sparen.","sideA":"Ressourcen schonen","sideB":"am falschen Ende sparen","dreh":"Wann ist Sparen Vorsorge – und wann eine Jagd ohne Ende?","szene":"Die Sneaker, die du willst, sind im Outlet am anderen Ende der Stadt 30 Euro günstiger. Die Fahrt kostet Zeit und ein Ticket. Fährst du hin? Und was könnte dich anders entscheiden lassen?","wenn":"… die Fahrt deinen einzigen freien Tag kostet?","bucay":"„Der Kreis der Neunundneunzig“: Ein zufriedener Diener erhält 99 Goldmünzen, jagt der hundertsten nach und verliert dabei seine Zufriedenheit.","bruecke":"Welche „hundertste Münze“ hält dich gerade beschäftigt?","joker":false},{"nr":"30","n":30,"title":"GROSSZÜGIGKEIT","titleSub":"","name":"Großzügigkeit","catId":5,"catName":"Meins, deins, unseres","catLabel":"Kategorie 5","color":"#18202E","tint":"rgba(24,32,46,0.08)","story":[{"t":"„Ich habe gestern alle eingeladen“, sagte er.","q":true},{"t":"„Wie schön.“","q":true},{"t":"„Es war ein wunderbarer Abend.“","q":true},{"t":"Die Frau lächelte.","q":false},{"t":"Er lächelte zurück, ein wenig angestrengt.","q":false},{"t":"„Was ist?“","q":true},{"t":"„Jetzt kann ich meine Stromrechnung nicht ganz bezahlen.“","q":true},{"t":"„Warum hast du die ganze Rechnung übernommen?“","q":true},{"t":"„Ich wollte ihnen etwas Gutes tun.“","q":true},{"t":"„Das ist dir gelungen.“","q":true},{"t":"Er nickte.","q":false},{"t":"„Und nun?“","q":true},{"t":"Die Frau überlegte.","q":false},{"t":"„Beim nächsten Mal könntest du für alle kochen.“","q":true},{"t":"„Das wäre günstiger.“","q":true},{"t":"„Und der Strom?“","q":true},{"t":"Er lachte.","q":false},{"t":"„Den sollte ich vorher bezahlen.“","q":true}],"sides":"Freude teilen ↔ die eigenen Mittel übersehen.","sideA":"Freude teilen","sideB":"die eigenen Mittel übersehen","dreh":"Wann ist Geben Freude – und wann eine stille Rechnung?","szene":"Du möchtest deine Freunde zu deinem Geburtstag in eure Lieblingsbar einladen. Die ganze Rechnung wäre diesen Monat allerdings spürbar. Wie gestaltest du die Einladung? Und was könnte dich anders entscheiden lassen?","wenn":"… die anderen lieber selbst zahlen würden?","bucay":"„Geschenke für den Maharadscha“: Ein Herrscher behält nur Geschenke ohne Namen – alles mit Absender gibt er zurück.","bruecke":"Gibst du gern – oder gern mit Absender?","joker":false},{"nr":"31","n":31,"title":"ORDNUNGSLIEBE","titleSub":"","name":"Ordnungsliebe","catId":5,"catName":"Meins, deins, unseres","catLabel":"Kategorie 5","color":"#18202E","tint":"rgba(24,32,46,0.08)","story":[{"t":"„Ich habe den Schreibtisch meiner Frau aufgeräumt.“","q":true},{"t":"„Hat sie sich gefreut?“","q":true},{"t":"„Sie sucht seit heute Morgen ihre Unterlagen.“","q":true},{"t":"„Wo sind sie?“","q":true},{"t":"„In beschrifteten Ordnern.“","q":true},{"t":"„Weiß sie das?“","q":true},{"t":"„Ich habe es ihr erklärt.“","q":true},{"t":"„Und?“","q":true},{"t":"„Sie sagt, sie hätte vorher alles gefunden.“","q":true},{"t":"Die Frau nahm seine Jacke und legte sie in ihre Tasche.","q":false},{"t":"„Was machst du?“","q":true},{"t":"„Aufräumen.“","q":true},{"t":"„Aber ich brauche die noch.“","q":true},{"t":"„Natürlich. Ich erkläre dir später mein System.“","q":true},{"t":"Er streckte die Hand aus.","q":false},{"t":"Sie gab ihm die Jacke zurück.","q":false},{"t":"„Die Ordner“, sagte er, „waren trotzdem wirklich schön beschriftet.“","q":true}],"sides":"Übersicht schaffen ↔ andere einengen.","sideA":"Übersicht schaffen","sideB":"andere einengen","dreh":"Wann schafft Ordnung Ruhe – und wann nur Regeln?","szene":"Die WG-Küche ist dir zu chaotisch. Die anderen finden sie gemütlich. Räumst du auf, lässt du alles stehen oder verhandelst du eine Lösung? Und was könnte dich anders entscheiden lassen?","wenn":"… deine Mitbewohner gerade mitten in der Prüfungsphase stecken?","bucay":"„Nicht mischen!“: Ein Diener soll Mehl und Zucker nicht mischen und hält sich so wörtlich daran, dass er beides verliert.","bruecke":"Wo hältst du an einer Ordnung fest, statt an ihrem Sinn?","joker":false},{"nr":"32","n":32,"title":"GENÜGSAMKEIT","titleSub":"","name":"Genügsamkeit","catId":5,"catName":"Meins, deins, unseres","catLabel":"Kategorie 5","color":"#18202E","tint":"rgba(24,32,46,0.08)","story":[{"t":"Sein Telefon klingelte. Er hielt es schräg, drückte gegen das Gehäuse und sagte sehr laut:","q":false},{"t":"„Hallo?“","q":true},{"t":"Dann war die Verbindung weg.","q":false},{"t":"„Du brauchst ein neues“, sagte die Frau.","q":true},{"t":"„Dieses funktioniert noch.“","q":true},{"t":"„Gerade nicht.“","q":true},{"t":"„Sonst meistens.“","q":true},{"t":"„Warum behältst du es?“","q":true},{"t":"„Ich muss nicht immer das Neueste haben.“","q":true},{"t":"Sie nickte.","q":false},{"t":"Er befestigte das Ladekabel mit einem Gummiband.","q":false},{"t":"„Ein anderes müsste nicht das Neueste sein“, sagte sie.","q":true},{"t":"Er sah auf das Telefon.","q":false},{"t":"Es klingelte erneut.","q":false},{"t":"Beide hielten den Atem an.","q":false}],"sides":"Zufrieden sein ↔ nötige Veränderungen aufschieben.","sideA":"Zufrieden sein","sideB":"nötige Veränderungen aufschieben","dreh":"Wann ist weniger genug – und wann nur Verzicht?","szene":"Dein altes Handy funktioniert noch, macht den Alltag aber zunehmend umständlich. Reparieren, ersetzen oder weiterbenutzen: Was tust du? Und was könnte dich anders entscheiden lassen?","wenn":"… ein neues Gerät dir täglich Zeit schenkt?","bucay":"„Zweimal Diogenes“: Ein Reicher will Diogenes Geld schenken; Diogenes fragt, ob er selbst noch mehr will – dann brauche er es dringender.","bruecke":"Wer ist reicher: wer viel hat oder wer nichts mehr braucht?","joker":false},{"nr":"33","n":33,"title":"UNABHÄNGIGKEIT","titleSub":"","name":"Unabhängigkeit","catId":5,"catName":"Meins, deins, unseres","catLabel":"Kategorie 5","color":"#18202E","tint":"rgba(24,32,46,0.08)","story":[{"t":"Er kam mit drei Taschen und einer Wassermelone.","q":false},{"t":"„Soll ich dir etwas abnehmen?“","q":true},{"t":"„Geht schon.“","q":true},{"t":"Er klemmte die Melone unter den Arm und suchte nach seinem Schlüssel.","q":false},{"t":"Eine Tasche rutschte.","q":false},{"t":"Die Frau fing sie auf.","q":false},{"t":"„Ich hatte sie“, sagte er.","q":true},{"t":"„Fast.“","q":true},{"t":"Er versuchte, die Haustür aufzuschließen. Die Melone begann langsam zu gleiten.","q":false},{"t":"Er sah die Frau an.","q":false},{"t":"Sie wartete.","q":false},{"t":"„Kannst du die kurz halten?“","q":true},{"t":"„Gern.“","q":true},{"t":"Mit freien Händen öffnete er die Tür.","q":false},{"t":"„Das ging schneller“, sagte er.","q":true},{"t":"„Du hast auch ganz allein darum gebeten.“","q":true}],"sides":"Selbstbestimmt sein ↔ Unterstützung ausschließen.","sideA":"Selbstbestimmt sein","sideB":"Unterstützung ausschließen","dreh":"Wann macht Selbstständigkeit frei – und wann einsam?","szene":"Du baust allein ein großes Regal auf. Zu zweit ginge es deutlich leichter. Fragst du jemanden? Und was könnte dich anders entscheiden lassen?","wenn":"… deine Nachbarin sich über die Frage freuen würde?","bucay":"„Allein oder in Begleitung“: Wir gehen den Weg allein – und trotzdem gibt es Weggefährten, die ein Stück mitgehen.","bruecke":"Wer geht gerade ein Stück deines Wegs mit?","joker":false},{"nr":"34","n":34,"title":"VERANTWORTUNGSGEFÜHL","titleSub":"","name":"Verantwortungsgefühl","catId":5,"catName":"Meins, deins, unseres","catLabel":"Kategorie 5","color":"#18202E","tint":"rgba(24,32,46,0.08)","story":[{"t":"„Ohne mich findet das Familienfest nicht statt“, sagte er.","q":true},{"t":"„Weil niemand sonst es kann?“","q":true},{"t":"„Weil niemand sonst es macht.“","q":true},{"t":"„Hast du jemanden gefragt?“","q":true},{"t":"„Sie wissen doch, was zu tun ist.“","q":true},{"t":"Die Frau nickte.","q":false},{"t":"„Und wenn nicht?“","q":true},{"t":"Er seufzte.","q":false},{"t":"Eine Woche später kam er ohne die übliche Liste.","q":false},{"t":"„Fest abgesagt?“","q":true},{"t":"„Nein. Meine Schwester organisiert das Essen. Mein Bruder die Getränke.“","q":true},{"t":"„Und du?“","q":true},{"t":"„Ich komme um drei.“","q":true},{"t":"Er lächelte.","q":false},{"t":"Dann runzelte er die Stirn.","q":false},{"t":"„Hoffentlich denkt jemand an Servietten.“","q":true},{"t":"Die Frau reichte ihm eine.","q":false},{"t":"„Für den Anfang.“","q":true}],"sides":"Verlässlich sein ↔ alles übernehmen.","sideA":"Verlässlich sein","sideB":"alles übernehmen","dreh":"Wann trägst du Verantwortung – und wann trägst du zu viel?","szene":"Wenn du den jährlichen Urlaub mit deiner Clique nicht organisierst, findet er möglicherweise nicht statt. Du möchtest die Aufgabe dieses Jahr abgeben. Übernimmst du trotzdem? Und was könnte dich anders entscheiden lassen?","wenn":"… die anderen nur darauf warten, dass du loslässt?","bucay":"„Der schwangere Topf“: Ein Nachbar nimmt die Geschichte vom „gebärenden“ Topf gern an, solange er gewinnt – bis der Topf „stirbt“.","bruecke":"Stehst du zu den Folgen auch dann, wenn sie dir nicht mehr nützen?","joker":false},{"nr":"35","n":35,"title":"GERECHTIGKEITSSINN","titleSub":"","name":"Gerechtigkeitssinn","catId":5,"catName":"Meins, deins, unseres","catLabel":"Kategorie 5","color":"#18202E","tint":"rgba(24,32,46,0.08)","story":[{"t":"Er schnitt den Kuchen in sechs gleich große Stücke.","q":false},{"t":"„So ist es gerecht.“","q":true},{"t":"„Ich möchte nur ein halbes“, sagte die Frau.","q":true},{"t":"„Dann bleiben die Stücke ungleich.“","q":true},{"t":"„Aber ich bin nicht so hungrig.“","q":true},{"t":"Er betrachtete den Kuchen.","q":false},{"t":"Ein Kind kam vorbei und blickte darauf.","q":false},{"t":"„Möchtest du etwas?“, fragte die Frau.","q":true},{"t":"Das Kind nickte heftig.","q":false},{"t":"Sie schob ihm ihre Hälfte hin.","q":false},{"t":"Er sah auf die unterschiedlich großen Portionen.","q":false},{"t":"„Jetzt stimmt es nicht mehr.“","q":true},{"t":"Die Frau nahm ihre Gabel.","q":false},{"t":"„Für mich schon.“","q":true},{"t":"Das Kind hatte den Mund zu voll, um zu antworten.","q":false}],"sides":"Fairness sichern ↔ unterschiedliche Bedürfnisse übersehen.","sideA":"Fairness sichern","sideB":"unterschiedliche Bedürfnisse übersehen","dreh":"Wann ist Gerechtigkeit fair – und wann nur gleich?","szene":"Ihr teilt die Kosten für ein Ferienhaus. Eine Person war nur zwei Nächte da, eine andere hat gerade kaum Geld. Wie würdest du die Summe aufteilen? Und was könnte dich anders entscheiden lassen?","wenn":"… die Person mit weniger Geld sich schämt, das anzusprechen?","bucay":"„Zurück zu den Münzen“: Ein Reicher will die Frömmigkeit eines Alten vorführen und landet vor einem Richter – der auch die Großmut des Betrogenen berücksichtigt.","bruecke":"Wann ist ein mildes Urteil gerechter als ein strenges?","joker":false},{"nr":"36","n":36,"title":"HUMOR","titleSub":"","name":"Humor","catId":6,"catName":"Das Leben mischt mit","catLabel":"Kategorie 6","color":"#5A6270","tint":"rgba(90,98,112,0.10)","story":[{"t":"„Ich habe im Seminar Kaffee verschüttet“, sagte er.","q":true},{"t":"„Schlimm?“","q":true},{"t":"„Auf einen Laptop.“","q":true},{"t":"„Oh.“","q":true},{"t":"„Ich habe gesagt: Jetzt läuft wenigstens etwas.“","q":true},{"t":"Die Frau lachte kurz.","q":false},{"t":"„Die anderen auch“, sagte er.","q":true},{"t":"„Und der Besitzer des Laptops?“","q":true},{"t":"„Nicht.“","q":true},{"t":"Sie nickte.","q":false},{"t":"„Ich wollte die Situation retten.“","q":true},{"t":"„Hast du ihm geholfen?“","q":true},{"t":"Er schwieg.","q":false},{"t":"Dann zog er sein Telefon hervor.","q":false},{"t":"„Was schreibst du?“","q":true},{"t":"„Dass es mir leidtut. Und dass ich für den Schaden aufkomme.“","q":true},{"t":"„Ohne Witz?“","q":true},{"t":"„Für diese Nachricht fällt mir gerade keiner ein.“","q":true}],"sides":"Spannung lösen ↔ Betroffenheit überspielen.","sideA":"Spannung lösen","sideB":"Betroffenheit überspielen","dreh":"Wann lockert Humor die Lage – und wann lacht er über jemanden?","szene":"Ein Freund verliert bei seiner Geburtstagsrede den Faden. Dir fällt ein Witz ein, der die Stimmung lockern könnte. Sagst du ihn? Und was könnte dich anders entscheiden lassen?","wenn":"… er kurz davor ist, rot anzulaufen und abzubrechen?","bucay":"„Was ist das eigentlich für eine Therapie?“: Ein Witz mit mehreren möglichen Enden zeigt, wie unterschiedlich man dieselbe Sache auffassen kann.","bruecke":"Lachst du mit – oder lachst du die Sache weg?","joker":false},{"nr":"37","n":37,"title":"SENSIBILITÄT","titleSub":"","name":"Sensibilität","catId":6,"catName":"Das Leben mischt mit","catLabel":"Kategorie 6","color":"#5A6270","tint":"rgba(90,98,112,0.10)","story":[{"t":"„Sie war heute so still“, sagte er.","q":true},{"t":"„Hast du gefragt, was los ist?“","q":true},{"t":"„Ja. Ihre Mutter ist krank.“","q":true},{"t":"„Gut, dass du es bemerkt hast.“","q":true},{"t":"Er nickte.","q":false},{"t":"„Aber beim Abschied hat sie kaum gelächelt.“","q":true},{"t":"Die Frau wartete.","q":false},{"t":"„Vielleicht war meine Frage falsch.“","q":true},{"t":"„Was hat sie gesagt?“","q":true},{"t":"„Dass es ihr gutgetan hat, davon zu erzählen.“","q":true},{"t":"„Dann würde ich ihr das glauben.“","q":true},{"t":"Er blickte auf seine Hände.","q":false},{"t":"„Ich spüre einfach so viel.“","q":true},{"t":"Die Frau nickte.","q":false},{"t":"„Heute vielleicht auch, wie anstrengend ihr Tag war.“","q":true}],"sides":"Fein wahrnehmen ↔ vieles auf dich beziehen.","sideA":"Fein wahrnehmen","sideB":"vieles auf dich beziehen","dreh":"Wann spürst du feine Signale – und wann deutest du zu viel hinein?","szene":"Eine Freundin antwortet seit Tagen nur noch knapp im Chat. Fragst du direkt nach, meldest du dich später oder lässt du es erst einmal stehen? Und was könnte dich anders entscheiden lassen?","wenn":"… sie einfach mitten im Prüfungsstress steckt?","bucay":"„Die taube Ehefrau“: Ein Mann hält seine Frau für schwerhörig – bis sich zeigt, dass er selbst es ist.","bruecke":"Hörst du gerade den anderen – oder dich selbst?","joker":false},{"nr":"38","n":38,"title":"BEGEISTERUNGSFÄHIGKEIT","titleSub":"","name":"Begeisterungsfähigkeit","catId":6,"catName":"Das Leben mischt mit","catLabel":"Kategorie 6","color":"#5A6270","tint":"rgba(90,98,112,0.10)","story":[{"t":"Er kam mit einer Gitarre.","q":false},{"t":"„Ich mache jetzt Musik.“","q":true},{"t":"„Spiel etwas.“","q":true},{"t":"„Ich habe erst gestern angefangen.“","q":true},{"t":"Am nächsten Tag brachte er einen Verstärker mit.","q":false},{"t":"Danach ein Mikrofon.","q":false},{"t":"Dann ein Aufnahmegerät.","q":false},{"t":"Die Frau betrachtete die Ausrüstung.","q":false},{"t":"„Was kannst du schon spielen?“","q":true},{"t":"„Ich suche noch den richtigen Kurs.“","q":true},{"t":"Sie zeigte auf die Gitarre.","q":false},{"t":"„Möchtest du sie mir reichen?“","q":true},{"t":"Er gab sie ihr.","q":false},{"t":"Sie schlug eine Saite an. Es klang schrecklich.","q":false},{"t":"Beide lachten.","q":false},{"t":"Er nahm die Gitarre zurück.","q":false},{"t":"„Das“, sagte er, „kann ich vermutlich auch.“","q":true}],"sides":"Energie entfachen ↔ dich vorschnell festlegen.","sideA":"Energie entfachen","sideB":"dich vorschnell festlegen","dreh":"Wann trägt Begeisterung dich – und wann verbrennt sie wie Stroh?","szene":"Du hast Bouldern für dich entdeckt. Schuhe, Kreide und eine Jahreskarte gibt es nur heute im Paket reduziert. Kaufst du oder leihst du dir erst ein paar Mal die Ausrüstung? Und was könnte dich anders entscheiden lassen?","wenn":"… schon drei Hobbys bei deinen Eltern im Keller liegen?","bucay":"„Der Dattelpalmenpflanzer“: Ein alter Mann pflanzt Dattelpalmen, die erst nach Jahrzehnten tragen – und freut sich schon jetzt daran.","bruecke":"Wofür brennst du, auch wenn du die Ernte vielleicht nicht selbst einfährst?","joker":false},{"nr":"39","n":39,"title":"NOSTALGIE","titleSub":"","name":"Nostalgie","catId":6,"catName":"Das Leben mischt mit","catLabel":"Kategorie 6","color":"#5A6270","tint":"rgba(90,98,112,0.10)","story":[{"t":"„Früher war alles leichter“, sagte er.","q":true},{"t":"„Was zum Beispiel?“","q":true},{"t":"„Die Sommer. Die Musik. Die Nächte mit meinen Freunden.“","q":true},{"t":"„Wie bist du nach Hause gekommen?“","q":true},{"t":"„Mit dem letzten Bus.“","q":true},{"t":"„Und wenn du ihn verpasst hast?“","q":true},{"t":"Er lächelte.","q":false},{"t":"„Dann bin ich gelaufen. Zwei Stunden.“","q":true},{"t":"„In deinen schönen Schuhen?“","q":true},{"t":"„Die haben fürchterlich gedrückt.“","q":true},{"t":"Eine Weile hörten sie einem Lied aus dem Café gegenüber zu.","q":false},{"t":"„Trotzdem war es schön“, sagte er.","q":true},{"t":"„Das glaube ich.“","q":true},{"t":"Sie stand auf.","q":false},{"t":"„Tanzen?“","q":true},{"t":"Er sah sich um.","q":false},{"t":"„Hier?“","q":true},{"t":"„Der Bus fährt heute häufiger.“","q":true}],"sides":"Verbundenheit spüren ↔ Vergangenes verklären.","sideA":"Verbundenheit spüren","sideB":"Vergangenes verklären","dreh":"Wann wärmt Erinnerung – und wann hält sie die Uhr an?","szene":"Deine alte Clique aus der Schulzeit plant ein Treffen in eurer Heimatstadt. Vieles und viele haben sich verändert. Fährst du hin? Und was könnte dich anders entscheiden lassen?","wenn":"… dort jemand ist, der dich wirklich gern wiedersehen würde?","bucay":"„Die Uhr, die auf sieben Uhr stehenblieb“: Eine stehengebliebene Uhr zeigt zweimal am Tag die richtige Zeit – Anlass, über die erfüllten Momente des Lebens nachzudenken.","bruecke":"Zu welcher Uhrzeit ist deine Erinnerung stehengeblieben?","joker":false},{"nr":"40","n":40,"title":"VORSICHT","titleSub":"","name":"Vorsicht","catId":6,"catName":"Das Leben mischt mit","catLabel":"Kategorie 6","color":"#5A6270","tint":"rgba(90,98,112,0.10)","story":[{"t":"Am See prüfte er die Wassertiefe.","q":false},{"t":"„Gut“, sagte die Frau.","q":true},{"t":"Er prüfte den Untergrund.","q":false},{"t":"Dann die Strömung.","q":false},{"t":"Dann die Wettervorhersage.","q":false},{"t":"Die Frau zog ihre Schuhe aus.","q":false},{"t":"„Es könnte kalt sein“, sagte er.","q":true},{"t":"Sie hielt einen Fuß hinein.","q":false},{"t":"„Ist es.“","q":true},{"t":"„Und?“","q":true},{"t":"„Ich überlege noch.“","q":true},{"t":"Das gefiel ihm.","q":false},{"t":"Er setzte sich neben sie und hielt ebenfalls einen Fuß ins Wasser.","q":false},{"t":"Eine Weile saßen sie so.","q":false},{"t":"Dann glitt sie hinein.","q":false},{"t":"Er sah ihr nach.","q":false},{"t":"„Wie ist es?“","q":true},{"t":"„Noch immer kalt.“","q":true},{"t":"Er lachte und rutschte von der Kante.","q":false}],"sides":"Risiken begrenzen ↔ Erlebnisse verpassen.","sideA":"Risiken begrenzen","sideB":"Erlebnisse verpassen","dreh":"Wann schützt Vorsicht – und wann sperrt sie ein?","szene":"Deine Freunde wollen im Urlaub von einem Felsen ins Meer springen. Es reizt dich, ist dir aber nicht ganz geheuer. Welche Informationen brauchst du, bevor du zu- oder absagst? Und was könnte dich anders entscheiden lassen?","wenn":"… alle anderen genauso unsicher sind wie du?","bucay":"„Die armen Schafe“: Hirten warnen ihre Schafe vor der Welt; als sie fortlaufen, fragt der Älteste, was nun aus den Hirten wird.","bruecke":"Wen schützt deine Vorsicht – die anderen oder dich?","joker":false},{"nr":"41","n":41,"title":"EHRLICHKEIT ZU DIR SELBST","titleSub":"","name":"Ehrlichkeit zu dir selbst","catId":6,"catName":"Das Leben mischt mit","catLabel":"Kategorie 6","color":"#5A6270","tint":"rgba(90,98,112,0.10)","story":[{"t":"„Ich habe abgesagt“, sagte er.","q":true},{"t":"„Weil du Ruhe brauchst?“","q":true},{"t":"„Ja.“","q":true},{"t":"Die Frau nickte.","q":false},{"t":"„Oder weil ich keine Lust hatte, dort jemanden kennenzulernen.“","q":true},{"t":"„Das könnte auch sein.“","q":true},{"t":"„Wie finde ich heraus, was stimmt?“","q":true},{"t":"Sie überlegte.","q":false},{"t":"„Stell dir vor, die Feier wäre nebenan. Du kennst alle. Niemand erwartet etwas von dir.“","q":true},{"t":"Er schloss kurz die Augen.","q":false},{"t":"„Ich wäre trotzdem lieber zu Hause.“","q":true},{"t":"„Dann geh nach Hause.“","q":true},{"t":"Er stand auf, blieb aber noch einmal stehen.","q":false},{"t":"„Und wenn es doch Angst ist?“","q":true},{"t":"„Dann kannst du auch das bemerken, wenn du dich ausgeruht hast.“","q":true}],"sides":"Eigene Bedürfnisse erkennen ↔ bequeme Erklärungen finden.","sideA":"Eigene Bedürfnisse erkennen","sideB":"bequeme Erklärungen finden","dreh":"Wann erkennst du dich ehrlich – und wann erzählst du dir eine bequeme Geschichte?","szene":"Du möchtest eine Einladung zur Hausparty absagen. Du weißt nicht, ob du Ruhe brauchst oder einer unangenehmen Begegnung mit deinem Ex ausweichst. Wie triffst du deine Entscheidung? Und was könnte dich anders entscheiden lassen?","wenn":"… auch dein Ex abgesagt hat?","bucay":"„Wer bist du?“: Ein Mann wird plötzlich von niemandem mehr erkannt – und spürt darin auch eine unerwartete Freiheit.","bruecke":"Wer bist du, wenn dich niemand erkennt?","joker":false},{"nr":"42","n":42,"title":"LOSLASSEN","titleSub":"","name":"Loslassen","catId":6,"catName":"Das Leben mischt mit","catLabel":"Kategorie 6","color":"#5A6270","tint":"rgba(90,98,112,0.10)","story":[{"t":"Er brachte eine alte Jacke mit.","q":false},{"t":"„Die möchte ich verschenken.“","q":true},{"t":"„Sie ist schön.“","q":true},{"t":"„Ich habe sie auf meiner ersten großen Reise getragen.“","q":true},{"t":"„Warum gibst du sie weg?“","q":true},{"t":"„Sie passt mir nicht mehr.“","q":true},{"t":"Die Frau strich über den abgewetzten Ärmel.","q":false},{"t":"„Fällt es dir schwer?“","q":true},{"t":"Er nickte.","q":false},{"t":"In einer Tasche fand er eine Fahrkarte. Er betrachtete sie lange.","q":false},{"t":"„Die behalte ich.“","q":true},{"t":"„Gut.“","q":true},{"t":"Er faltete die Jacke zusammen.","q":false},{"t":"„Ist das jetzt nur halb losgelassen?“","q":true},{"t":"Die Frau schüttelte den Kopf.","q":false},{"t":"„Die Fahrkarte braucht immerhin keinen eigenen Kleiderbügel.“","q":true}],"sides":"Frei werden ↔ etwas aufgeben, das dir wichtig war.","sideA":"Frei werden","sideB":"etwas aufgeben, das dir wichtig war","dreh":"Wann befreit dich Loslassen – und wann gibst du zu schnell auf?","szene":"Dein altes Skateboard steht seit Jahren in der Ecke. Du verbindest damit die besten Sommer deiner Jugend. Behalten, verschenken oder noch einmal draufstellen: Was tust du? Und was könnte dich anders entscheiden lassen?","wenn":"… jemand anderes genau diesen Gegenstand dringend braucht?","bucay":"„Tischlerei „Numero sieben““: Ein Tischler hilft einem Freund, der trinkt, erlebt Rückfälle mit – und lernt, dass Helfen manchmal Loslassen heißt.","bruecke":"Was müsstest du loslassen, damit etwas anderes wachsen kann?","joker":false},{"nr":"43","n":43,"title":"GEDULD","titleSub":"Die birne","name":"Geduld","catId":0,"catName":"Zusatzkarte · Joker","catLabel":"Zusatzkarte","color":"#C42E7C","tint":"rgba(196,46,124,0.10)","story":[{"t":"„Ich habe ihm noch eine Woche gegeben“, sagte er.","q":true},{"t":"„Worauf wartest du?“","q":true},{"t":"„Dass er mir das geliehene Geld zurückzahlt.“","q":true},{"t":"„Wann wollte er es bringen?“","q":true},{"t":"„Im März.“","q":true},{"t":"Die Frau nahm eine Birne aus ihrer Tasche. Er griff danach.","q":false},{"t":"„Die ist noch hart“, sagte sie.","q":true},{"t":"Er zog die Hand zurück.","q":false},{"t":"„Dann warte ich.“","q":true},{"t":"Sie legte die Birne zwischen sie auf die Bank.","q":false},{"t":"„Hat er dir gesagt, warum er nicht zahlt?“","q":true},{"t":"„Er braucht Zeit. Ich will ihn nicht drängen.“","q":true},{"t":"„Das verstehe ich.“","q":true},{"t":"„Man muss eben Geduld haben.“","q":true},{"t":"Eine Weile betrachteten sie die Birne.","q":false},{"t":"„Bis wann?“, fragte er schließlich.","q":true},{"t":"„Ein paar Tage.“","q":true},{"t":"„Und wenn sie dann immer noch hart ist?“","q":true},{"t":"„Dann schauen wir noch einmal.“","q":true},{"t":"„Und nach einem Jahr?“","q":true},{"t":"Sie sah ihn an.","q":false},{"t":"„Dann würde ich langsam bezweifeln, dass wir auf eine Birne warten.“","q":true}],"sides":"Etwas reifen lassen ↔ dich vertrösten lassen.","sideA":"Etwas reifen lassen","sideB":"dich vertrösten lassen","dreh":"Wann gibst du einer Sache Zeit – und wann wird es Zeit, etwas zu tun?","szene":"Ein Freund verschiebt die Rückzahlung deines Geldes erneut. Du brauchst es nicht sofort, möchtest aber nicht länger hingehalten werden. Wartest du, fragst du nach einem verbindlichen Termin oder setzt du eine Frist? Und was könnte dich anders entscheiden lassen?","wenn":"… er dir aus Scham nicht gesagt hat, dass er seine Arbeit verloren hat?","bucay":"„Der Dattelpalmenpflanzer“: Ein alter Mann pflanzt Bäume, deren Früchte er womöglich nie erntet – und spürt die Ernte trotzdem schon. (Zwillingskarte zu 38)","bruecke":"Worauf wartest du – auf eine Frucht oder auf eine Ausrede?","joker":true}]};